codeExample:
// The existing Database Record:
// { id: 1, name: "John", age: 30, role: "Admin" }

// ❌ BAD PUT REQUEST (Missing data!)
fetch('/api/users/1', {
  method: 'PUT',
  body: JSON.stringify({ name: "Johnny" })
})
// Result: { id: 1, name: "Johnny", age: null, role: null }
// It completely replaced the record and wiped out the age and role!

// ✅ GOOD PUT REQUEST (Send everything)
fetch('/api/users/1', {
  method: 'PUT',
  body: JSON.stringify({ name: "Johnny", age: 30, role: "Admin" })
})
